// Shows the name of each tone's selected wave under its Wave dial (#30).
//
// inlet 0: "wave <tone address 16/18/20/22> <wave group 0-20> <wave number 1-255>" from the Wave sections
//          (s/r ---wavename). Group 0 = INT-A, 1 = INT-B, 2..20 = SR-JV80 board 1..19.
//
// Names come from jv2080_names.js, generated by tools/import_wave_names.py. One instance in the main
// patch on purpose: freezing would copy the names file once per instance otherwise.

include("jv2080_names.js");

autowatch = 1;
inlets = 1;
outlets = 0;
setinletassist(0, "wave <tone address> <group> <number>");

var jsthis = this;

function groupKey(group) {
	if (group === 0) {
		return "INT-A";
	}
	if (group === 1) {
		return "INT-B";
	}
	var board = group - 1;
	return "SR-" + (board < 10 ? "0" : "") + board;
}

function name(group, number) {
	var list = JV2080_WAVE_NAMES[groupKey(group)];
	return list && list[number - 1] ? list[number - 1] : "";
}

function wave(a3, group, number) {
	var tone = (a3 - 16) / 2 + 1;
	if (tone !== 1 && tone !== 2 && tone !== 3 && tone !== 4) {
		return;
	}
	var box = jsthis.patcher.getnamed("WG_" + tone);
	var label = box ? box.subpatcher().getnamed("WaveName") : null;
	if (label) {
		label.message("set", name(group, Math.round(number)));
	}
}
